package pe.edu.vallegrande.crud.model;
import jakarta.persistence.*; import jakarta.validation.constraints.*; import java.time.LocalDateTime;
@Entity @Table(name="section_course", uniqueConstraints=@UniqueConstraint(name="UQ_section_course",columnNames={"section_id","course_id"}))
public class SectionCourse { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="section_course_id") private Integer id; @NotNull @Column(name="section_id",nullable=false) private Long sectionId; @NotNull @Column(name="course_id",nullable=false) private Integer courseId; @NotNull @Column(name="teacher_id",nullable=false) private Integer teacherId; @Column(nullable=false,length=15) private String status="ACTIVE"; @Column(name="created_at",insertable=false,updatable=false) private LocalDateTime createdAt; public Integer getId(){return id;} public void setId(Integer v){id=v;} public Long getSectionId(){return sectionId;} public void setSectionId(Long v){sectionId=v;} public Integer getCourseId(){return courseId;} public void setCourseId(Integer v){courseId=v;} public Integer getTeacherId(){return teacherId;} public void setTeacherId(Integer v){teacherId=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDateTime getCreatedAt(){return createdAt;} }
